<?php if (!in_array($_SESSION['role'],['admin','pimpinan','peserta'],true)){http_response_code(403);exit('Akses ditolak.');} ?><h1>Data Peserta</h1><?php if(in_array($_SESSION['role'],['admin','peserta'],true)): ?><section class="card"><h2>Tambah Peserta</h2><form method="post"><input type="hidden" name="csrf" value="<?=esc(csrf())?>"><div class="formgrid"><label>Nomor Induk<input name="nomor_induk" maxlength="50" required></label><label>Nama<input name="nama" maxlength="180" required></label><label>Angkatan<input name="angkatan" maxlength="30"></label><label>Nama Wali<input name="nama_wali" maxlength="180"></label></div><button name="action" value="add_peserta">Simpan</button></form></section><?php endif; ?><section class="card"><h2>Daftar Peserta</h2><div class="tablewrap"><table><thead><tr><th>Nomor Induk</th><th>Nama</th><th>Angkatan</th><th>Wali</th><th>Status</th></tr></thead><tbody><?php foreach(db()->query('SELECT nomor_induk,nama,angkatan,nama_wali,status FROM participants ORDER BY id DESC LIMIT 200') as $r): ?><tr><td><?=esc($r['nomor_induk'])?></td><td><?=esc($r['nama'])?></td><td><?=esc($r['angkatan'])?></td><td><?=esc($r['nama_wali'])?></td><td><?=esc($r['status'])?></td></tr><?php endforeach; ?></tbody></table></div></section>